 @Before public void start(){PreferenceManager.getDefaultSharedPreferences(RuntimeEnvironment.getApplication()).edit().clear().putString("app_theme","dark").commit();a=Robolectric.buildActivity(Host.class).setup().get();}
 private static void layout(View v,int w,int h){v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);}
 private static void drag(View v,float x,float y,float dx,float dy){long time=SystemClock.uptimeMillis();for(int i=0;i<3;i++){MotionEvent e=MotionEvent.obtain(time,time+i*80,i==0?0:i==1?2:1,x+dx*i/2,y+dy*i/2,0);v.dispatchTouchEvent(e);e.recycle();}}
 private static <T extends View>T find(View v,Class<T> c){if(c.isInstance(v))return c.cast(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){T x=find(g.getChildAt(i),c);if(x!=null)return x;}}return null;}
 @Test public void blankAreasInBothPagersHandleEmptyLoadingAndShortLists(){for(int content:new int[]{0,1,100,700}){Ui110.Swipe swipe=new Ui110.Swipe(a,4,n->{});FrameLayout page=new FrameLayout(a);TextView rows=new TextView(a);rows.setText(content==0?"No content":"Loading or rows");page.addView(rows,new FrameLayout.LayoutParams(-1,content));swipe.addView(page,new FrameLayout.LayoutParams(-1,-1));layout(swipe,360,640);drag(swipe,280,580,-220,0);assertEquals("bottom blank area: "+content,1,swipe.selected);}Following190.Pager following=new Following190.Pager(a);for(int i=0;i<3;i++)following.addView(new FrameLayout(a),new FrameLayout.LayoutParams(-1,-1));layout(following,360,640);drag(following,280,580,-220,0);assertEquals(1,following.selected);}
 @Test public void verticalScrollAndHorizontalChildrenKeepTheirGestures(){Ui110.Swipe parent=new Ui110.Swipe(a,4,n->{});FrameLayout page=new FrameLayout(a);View horizontal=new View(a){public boolean canScrollHorizontally(int direction){return true;}};page.addView(horizontal,new FrameLayout.LayoutParams(-1,200));parent.addView(page,new FrameLayout.LayoutParams(-1,-1));layout(parent,360,640);drag(parent,280,100,-220,0);assertEquals(0,parent.selected);drag(parent,200,500,0,-220);assertEquals(0,parent.selected);drag(parent,280,500,-220,0);assertEquals(1,parent.selected);}
 @Test public void playlistFabIsAtBottomWithZeroOneAndSeveralRows()throws Exception{for(int count:new int[]{0,1,4,25}){LocalPlaylistData data=new LocalPlaylistData("{}");for(int i=0;i<count;i++)data.folder("List "+i);PreferenceManager.getDefaultSharedPreferences(a).edit().putString("nicoid_local_playlists_v1",data.toString()).commit();LocalPlaylists.Page page=new LocalPlaylists.Page(a);page.render();LinearLayout nativeContainer=new LinearLayout(a);nativeContainer.addView(page.root);layout(nativeContainer,360,640);assertEquals(640,page.root.getHeight());FrameLayout frame=(FrameLayout)page.root.getChildAt(0);Button fab=(Button)frame.getChildAt(frame.getChildCount()-1);assertEquals(frame.getHeight()-PanelUi.dp(a,20),fab.getBottom());ScrollView scroll=(ScrollView)frame.getChildAt(0);scroll.scrollTo(0,100);assertEquals(frame.getHeight()-PanelUi.dp(a,20),fab.getBottom());LinearLayout items=(LinearLayout)scroll.getChildAt(0);View row=items.getChildAt(0);assertTrue("compact row: "+row.getHeight()+" px at density "+a.getResources().getDisplayMetrics().density,row.getHeight()<=PanelUi.dp(a,64));}}
 @Test public void ngListFooterStaysAtBottomAndRowsAreCompact(){PreferenceActivity host=Robolectric.buildActivity(PreferencesHost.class).setup().get();ContentFilter.save(host,new JSONArray());FilterUi110.Page page=new FilterUi110.Page(host);page.show();layout(page.root,340,600);View footer=page.root.getChildAt(page.root.getChildCount()-1);assertEquals(600-page.root.getPaddingBottom(),footer.getBottom());assertTrue(page.swipe.getHeight()>400);page.dialog.dismiss();}
 @Test public void ngEditorKeepsManagedInputCenteredAndSegmentsEqual()throws Exception{JSONArray data=new JSONArray();FilterUi110.edit(a,data,null,0,()->{});AlertDialog dialog=(AlertDialog)ShadowDialog.getLatestDialog();View decor=dialog.getWindow().getDecorView();layout(decor,360,640);EditText field=(EditText)decor.findViewWithTag("nicoid-managed-input");assertNotNull(field);assertEquals(Gravity.CENTER_VERTICAL,field.getGravity()&Gravity.VERTICAL_GRAVITY_MASK);assertNull(field.getBackgroundTintList());assertTrue(field.getHeight()<=PanelUi.dp(a,56));field.requestFocus();DialogInputs.pad(decor);assertEquals(0,((ViewGroup.MarginLayoutParams)field.getLayoutParams()).topMargin);assertEquals(Gravity.CENTER_VERTICAL,field.getGravity()&Gravity.VERTICAL_GRAVITY_MASK);dialog.dismiss();}
 @Test public void darkSurfaceFixLeavesMediaAndExplicitLightModeAlone(){LinearLayout page=new LinearLayout(a);TextView text=new TextView(a);text.setTextColor(Color.BLACK);text.setBackgroundColor(Color.WHITE);page.addView(text);ImageView image=new ImageView(a);ColorDrawable pixels=new ColorDrawable(Color.MAGENTA);image.setImageDrawable(pixels);image.setBackgroundColor(Color.WHITE);page.addView(image);UiTheme191.surface(page);assertEquals(DialogColors.INK_DARK,text.getCurrentTextColor());assertEquals(UiDialogs.surface(a),((ColorDrawable)text.getBackground()).getColor());assertSame(pixels,image.getDrawable());assertEquals(Color.WHITE,((ColorDrawable)image.getBackground()).getColor());PreferenceManager.getDefaultSharedPreferences(a).edit().putString("app_theme","light").commit();text.setTextColor(Color.BLACK);text.setBackgroundColor(Color.WHITE);UiTheme191.surface(page);assertEquals(Color.BLACK,text.getCurrentTextColor());assertEquals(Color.WHITE,((ColorDrawable)text.getBackground()).getColor());}

 @Test public void dialogActionsHave44dpPillsAnd48dpTargets(){FilterUi110.edit(a,new JSONArray(),null,0,()->{});AlertDialog d=(AlertDialog)ShadowDialog.getLatestDialog();layout(d.getWindow().getDecorView(),360,640);Button ok=d.getButton(-1),cancel=d.getButton(-2);assertEquals(PanelUi.dp(a,48),ok.getHeight());assertTrue("OK width="+ok.getWidth()+" density="+a.getResources().getDisplayMetrics().density,ok.getWidth()>=PanelUi.dp(a,72));assertTrue("Cancel height="+cancel.getHeight(),cancel.getHeight()>=PanelUi.dp(a,48));assertEquals(14f,ok.getTextSize()/a.getResources().getDisplayMetrics().scaledDensity,.1);assertEquals(0xff101114,ok.getCurrentTextColor());d.dismiss();}
