 @Test public void dividerPalettePreservesNativeHeightAndIgnoresTabLines(){ListView list=new ListView(a);list.setDivider(new ColorDrawable(Color.WHITE));list.setDividerHeight(1);LinearLayout page=new LinearLayout(a);page.addView(list);View tab=new View(a);tab.setBackgroundColor(0xff00c8a2);page.addView(tab);View separator=new View(a);separator.setTag("nicoid-list-divider");page.addView(separator);ListDividers191.tree(page);assertEquals(0x22eeeeee,((ColorDrawable)list.getDivider()).getColor());assertEquals(1,list.getDividerHeight());assertEquals(0xff00c8a2,((ColorDrawable)tab.getBackground()).getColor());assertEquals(0x22eeeeee,((ColorDrawable)separator.getBackground()).getColor());PreferenceManager.getDefaultSharedPreferences(a).edit().putString("app_theme","light").commit();ListDividers191.tree(page);assertEquals(0x22202124,((ColorDrawable)list.getDivider()).getColor());}
 @Test public void longHoldingNgWordAsksBeforeDeleting()throws Exception{PreferenceActivity host=Robolectric.buildActivity(PreferencesHost.class).setup().get();JSONArray rules=new JSONArray();rules.put(new JSONObject().put("value","test").put("category",0));ContentFilter.save(host,rules);FilterUi110.Page page=new FilterUi110.Page(host);page.show();assertTrue(page.items.getChildAt(0).performLongClick());AlertDialog confirm=(AlertDialog)ShadowDialog.getLatestDialog();assertNotNull(confirm.getButton(-1));assertEquals(1,ContentFilter.stored(host).length());confirm.getButton(-2).performClick();assertEquals(1,ContentFilter.stored(host).length());page.items.getChildAt(0).performLongClick();confirm=(AlertDialog)ShadowDialog.getLatestDialog();confirm.getButton(-1).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(0,ContentFilter.stored(host).length());page.dialog.dismiss();}
 public static class SelectionOwner {public Activity o0;public View Z;public boolean k0;public int g0=8,h0=0;public TextView selectionCount;public java.util.ArrayList<SelectionRow> a0=new java.util.ArrayList<>();public BaseAdapter p0=new BaseAdapter(){public int getCount(){return a0.size();}public Object getItem(int n){return a0.get(n);}public long getItemId(int n){return n;}public View getView(int n,View old,ViewGroup parent){return new TextView(o0);}};public void updateSelectionCount(){}public void Y(){k0=!k0;BulkSelection.modeChanged(this);}}
