 @Test public void nativeSelectionMovesCountAboveListAndRetainsMenuOperations()throws Exception{SelectionOwner owner=new SelectionOwner();owner.o0=a;android.widget.RelativeLayout root=new android.widget.RelativeLayout(a);owner.Z=root;ListView list=new ListView(a);root.addView(list,new android.widget.RelativeLayout.LayoutParams(-1,-1));LinearLayout footer=PanelUi.column(a);footer.setId(0x7f0801be);LinearLayout all=new LinearLayout(a);all.setId(0x7f08019a);footer.addView(all);LinearLayout actions=new LinearLayout(a);actions.setId(0x7f0801bd);footer.addView(actions);root.addView(footer);owner.a0.add(new SelectionRow());owner.a0.add(new SelectionRow());assertTrue(BulkSelection.enter(owner,0));assertEquals("1件選択",owner.selectionCount.getText().toString());assertSame(list.getParent(),owner.selectionCount.getParent());assertEquals(0,((LinearLayout)list.getParent()).indexOfChild(owner.selectionCount));PopupMenu popup=new PopupMenu(a,list);BulkSelection.menu(a,popup.getMenu());assertEquals(2,popup.getMenu().size());popup.getMenu().performIdentifierAction(popup.getMenu().getItem(0).getItemId(),0);BulkSelection.selectAll(owner,true);assertEquals("2件選択",owner.selectionCount.getText().toString());BulkSelection.selectAll(owner,false);assertEquals("0件選択",owner.selectionCount.getText().toString());LinearLayout controls=(LinearLayout)actions.getChildAt(0);assertFalse(controls.getChildAt(0).isEnabled());BulkSelection.done(owner);assertFalse(owner.k0);assertEquals(View.GONE,owner.selectionCount.getVisibility());}
 @Test public void detailItemBackgroundIsFlatGrayAndDoesNotTouchLightMode(){TextView item=new TextView(a);item.setTextColor(0xffeeeeee);item.setTextSize(16);LinearLayout root=new LinearLayout(a);root.setBackgroundColor(0xff191b20);root.addView(item);PlayerTheme.detailItem(item);RippleDrawable bg=(RippleDrawable)item.getBackground();assertEquals(0xff292b31,((ColorDrawable)bg.getDrawable(0)).getColor());assertEquals(0xff191b20,((ColorDrawable)root.getBackground()).getColor());assertEquals(0xffeeeeee,item.getCurrentTextColor());PreferenceManager.getDefaultSharedPreferences(a).edit().putString("app_theme","light").commit();TextView light=new TextView(a);ColorDrawable original=new ColorDrawable(Color.WHITE);light.setBackground(original);PlayerTheme.detailItem(light);assertSame(original,light.getBackground());}

 @Test public void tagsAreIndependentFlatRowsInBothThemesWithUnchangedGeometryAndClicks(){for(String theme:new String[]{"dark","light"}){PreferenceManager.getDefaultSharedPreferences(a).edit().putString("app_theme",theme).commit();LinearLayout tags=PanelUi.column(a);tags.setBackgroundColor(0xff292b31);int[] clicks={0};for(int n=0;n<3;n++){Button b=new Button(a);b.setText("Tag "+n);b.setTextSize(14);b.setPadding(16,6,16,6);b.setElevation(6);b.setOnClickListener(v->clicks[0]++);b.setOnLongClickListener(v->{clicks[0]+=10;return true;});tags.addView(b,new LinearLayout.LayoutParams(320,48));}PlayerTheme.tagRows(tags);layout(tags,320,180);assertEquals(Color.TRANSPARENT,((ColorDrawable)tags.getBackground()).getColor());for(int n=0;n<3;n++){Button b=(Button)tags.getChildAt(n);assertTrue(b.getBackground() instanceof RippleDrawable);assertEquals(theme.equals("dark")?0xff24262b:0xfff0f0f0,((ColorDrawable)((RippleDrawable)b.getBackground()).getDrawable(0)).getColor());assertEquals(320,b.getWidth());assertEquals(48,b.getHeight());assertEquals(16,b.getPaddingLeft());assertEquals(14f,b.getTextSize()/a.getResources().getDisplayMetrics().scaledDensity,.1);assertEquals(0f,b.getElevation(),0);assertNull(b.getStateListAnimator());if(n<2)assertEquals(PanelUi.dp(a,4),tags.getChildAt(n+1).getTop()-b.getBottom());b.performClick();b.performLongClick();}assertEquals(33,clicks[0]);PlayerTheme.tagRows(tags);assertEquals(4,((LinearLayout.LayoutParams)tags.getChildAt(0).getLayoutParams()).bottomMargin);}}
 @Test public void flatControlsPreserveShapeAndOverlayOrderWhileRemovingShadows(){LinearLayout column=PanelUi.column(a);Button button=new Button(a);GradientDrawable shape=PanelUi.round(a,0xff24262b,12);button.setBackground(shape);button.setElevation(6);button.setTranslationZ(4);button.setShadowLayer(3,1,1,Color.BLACK);column.addView(button,new LinearLayout.LayoutParams(120,48));FlatUi191.tree(column);assertEquals(0,button.getElevation(),0);assertEquals(0,button.getTranslationZ(),0);assertEquals(0,button.getShadowRadius(),0);assertSame(shape,button.getBackground());assertEquals(PanelUi.dp(a,12),shape.getCornerRadius(),0);FrameLayout overlay=new FrameLayout(a);View front=new View(a);front.setBackground(PanelUi.round(a,Color.GRAY,12));front.setElevation(12);overlay.addView(front);FlatUi191.tree(overlay);assertEquals(12,front.getElevation(),0);android.graphics.Outline outline=new android.graphics.Outline();front.getOutlineProvider().getOutline(front,outline);assertEquals(0f,outline.getAlpha(),0);assertEquals(Color.TRANSPARENT,front.getOutlineAmbientShadowColor());}
 @Test public void flatPolicyPreservesMediaPixelsAndVideoReadabilityEffects(){ImageView thumbnail=new ImageView(a);ColorDrawable pixels=new ColorDrawable(Color.MAGENTA);thumbnail.setImageDrawable(pixels);thumbnail.setPadding(3,4,5,6);FlatUi191.tree(thumbnail);assertSame(pixels,thumbnail.getDrawable());assertEquals(3,thumbnail.getPaddingLeft());TextView overlay=new TextView(a);overlay.setTag("nicoid-media-overlay");overlay.setShadowLayer(3,0,1,Color.BLACK);FlatUi191.tree(overlay);assertEquals(3,overlay.getShadowRadius(),0);}
